// Writes src/npc/HitClips.ts from tools/blender/hit_clips.json (exported by export_clips.py).
import { readFileSync, writeFileSync } from "node:fs";

type Exported = {
    bones: string[];
    joints: number[][];
    clips: Record<string, { fps: number; loop: boolean; frames: { r: number[]; t: number[] }[] }>;
};

const src = JSON.parse(readFileSync("tools/blender/hit_clips.json", "utf8")) as Exported;
const round = (v: number) => Math.round(v * 1e4) / 1e4;
const lines = [
    "// Generated by tools/blender/gen_hit_clips.ts from tools/blender/hit_reactions.blend; do not edit.",
    "",
    "/** Bones of the humanoid hit-reaction rig, in the order each frame stores them. */",
    `export const HIT_BONES = ${JSON.stringify(src.bones)} as const;`,
    "",
    "/** Height of the rig's neck joint (tiles): pelvis offsets scale with a body's own. */",
    `export const HIT_RIG_NECK_HEIGHT = ${round(src.joints[src.bones.indexOf("head")][1])};`,
    "",
    "/** Each bone's joint in the authoring rig (x, y, z per bone, model space, tiles). */",
    `export const HIT_RIG_JOINTS = [${src.joints.flat().map(round).join(", ")}];`,
    "",
    "/**",
    " * A hit reaction: per frame, each bone's rotation (x, y, z, w) relative to its parent about its",
    " * joint, in model axes (+x the body's left, +y up, +z forward), then the pelvis offset (tiles).",
    " */",
    "export type HitClip = { fps: number; loop: boolean; frames: number; data: Float32Array };",
    "",
    "const clip = (fps: number, loop: boolean, data: number[]): HitClip => ({",
    "    fps,",
    "    loop,",
    `    frames: data.length / ${src.bones.length * 4 + 3},`,
    "    data: new Float32Array(data),",
    "});",
    "",
    "export const HIT_CLIPS = {",
];
for (const [name, c] of Object.entries(src.clips)) {
    const data = c.frames.flatMap((f) => [...f.r, ...f.t]).map(round);
    lines.push(`    ${name}: clip(${c.fps}, ${c.loop}, [${data.join(", ")}]),`);
}
lines.push("};", "", "export type HitClipName = keyof typeof HIT_CLIPS;", "");
writeFileSync("src/npc/HitClips.ts", lines.join("\n"));
console.log("wrote src/npc/HitClips.ts:", Object.keys(src.clips).join(", "));
